//! Windows To Go: run Windows from the USB drive.
//!
//! Windows does this with its own tools (`bcdboot.exe`, `dism.exe`). Here
//! the same steps are done without Windows:
//!
//!   1. partition: a 300 MiB FAT32 boot partition (ESP) and an NTFS partition;
//!   2. `wimlib-imagex apply` writes the chosen edition straight onto the NTFS
//!      volume (keeping security descriptors, streams and reparse points);
//!   3. the boot files are copied out of `Windows\Boot` the way bcdboot does,
//!      and the BCD stores are generated by [`crate::bcd`];
//!   4. an answer file in `Windows\Panther` applies the user's choices and
//!      keeps the PC's own disks offline;
//!   5. legacy BIOS boot goes through GRUB, which hands over to `bootmgr`.

use std::fs::OpenOptions;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::AtomicBool;

use crate::bcd::{self, Firmware, Part};
use crate::disks;
use crate::unattend;
use crate::winopts::{Fs, Scheme, WinOptions};
use crate::winworker::{
    check_cancel, command, find_ci, mount_data, parse_image_count, parse_image_info, parse_percent,
    require, run_quiet, run_stream, s, strip_ex, wait_for_node, wim_info_text, InstallKind, Report,
    Tool, Workdir, GRUB, GRUB_CFG, MIB, MKFS_FAT, MKFS_NTFS, PARTED, WIMLIB,
};
use crate::worker::{partition_path, progress, stage, unmount_all, Job};

const SFDISK: Tool = Tool {
    names: &["sfdisk"],
    install: "util-linux",
};

/// Size of the FAT32 boot partition.
pub const ESP_MIB: u64 = 300;
/// A Windows installation needs room; below this it cannot work.
const MIN_DRIVE: u64 = 12 * 1024 * MIB;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Layout {
    pub esp: (u64, u64),
    pub os: (u64, u64),
}

/// Whole MiB; the last MiB stays free for the GPT backup table.
pub fn layout(size_bytes: u64) -> Result<Layout, String> {
    if size_bytes < MIN_DRIVE {
        return Err(format!(
            "The drive is too small ({}). Windows To Go needs at least 16 GB.",
            disks::human_size(size_bytes)
        ));
    }
    let total = size_bytes / MIB;
    Ok(Layout {
        esp: (1, 1 + ESP_MIB),
        os: (1 + ESP_MIB, total - 1),
    })
}

pub fn parted_commands(dev: &str, o: &WinOptions, lay: &Layout) -> Vec<Vec<String>> {
    let gpt = o.scheme == Scheme::Gpt;
    let mk = |name: &str, fs: &str, r: (u64, u64)| {
        s(&[
            "-s",
            dev,
            "mkpart",
            if gpt { name } else { "primary" },
            fs,
            &format!("{}MiB", r.0),
            &format!("{}MiB", r.1),
        ])
    };
    let mut v = vec![
        s(&["-s", dev, "mklabel", if gpt { "gpt" } else { "msdos" }]),
        mk("EFI", "fat32", lay.esp),
        mk("Windows", "ntfs", lay.os),
        s(&["-s", dev, "set", "1", "esp", "on"]),
    ];
    if !gpt && o.target.wants_bios() {
        // the BIOS only boots an active partition
        v.push(s(&["-s", dev, "set", "1", "boot", "on"]));
    }
    v
}

/// The partitions' identities as the boot manager wants them, read from
/// `sfdisk --json` (partition numbers are 1-based, in table order).
pub fn parse_sfdisk(json: &str, wanted: &[usize]) -> Result<Vec<Part>, String> {
    let v: serde_json::Value =
        serde_json::from_str(json).map_err(|e| format!("cannot read the partition table: {}", e))?;
    let t = v
        .get("partitiontable")
        .ok_or("sfdisk printed no partition table")?;
    let label = t.get("label").and_then(|x| x.as_str()).unwrap_or("");
    let id = t.get("id").and_then(|x| x.as_str()).unwrap_or("");
    let sector = t.get("sectorsize").and_then(|x| x.as_u64()).unwrap_or(512);
    let parts = t
        .get("partitions")
        .and_then(|x| x.as_array())
        .ok_or("the drive has no partitions")?;
    let mut out = Vec::new();
    for &n in wanted {
        let p = parts
            .get(n - 1)
            .ok_or_else(|| format!("partition {} is missing", n))?;
        match label {
            "gpt" => {
                let uuid = p
                    .get("uuid")
                    .and_then(|x| x.as_str())
                    .ok_or("a partition has no GUID")?;
                out.push(Part::gpt(id, uuid)?);
            }
            "dos" => {
                let sig = u32::from_str_radix(id.trim_start_matches("0x"), 16)
                    .map_err(|_| format!("bad disk signature '{}'", id))?;
                let start = p
                    .get("start")
                    .and_then(|x| x.as_u64())
                    .ok_or("a partition has no start")?;
                out.push(Part::Mbr {
                    signature: sig,
                    offset: start * sector,
                });
            }
            other => return Err(format!("unsupported partition table '{}'", other)),
        }
    }
    Ok(out)
}

fn copy_dir(src: &Path, dst: &Path, strip: bool, log: &mut Vec<String>) -> Result<(), String> {
    std::fs::create_dir_all(dst).map_err(|e| format!("cannot create {}: {}", dst.display(), e))?;
    let rd = std::fs::read_dir(src).map_err(|e| format!("cannot read {}: {}", src.display(), e))?;
    let mut entries: Vec<_> = rd.filter_map(Result::ok).collect();
    entries.sort_by_key(|e| e.file_name());
    for e in entries {
        let name = e.file_name().to_string_lossy().into_owned();
        let target_name = if strip { strip_ex(&name) } else { name };
        let path = e.path();
        let ft = e
            .file_type()
            .map_err(|er| format!("{}: {}", path.display(), er))?;
        if ft.is_dir() {
            copy_dir(&path, &dst.join(&target_name), strip, log)?;
        } else if ft.is_file() {
            std::fs::copy(&path, dst.join(&target_name))
                .map_err(|er| format!("cannot copy {}: {}", path.display(), er))?;
        }
    }
    Ok(())
}

/// The removable-media fallback name UEFI looks for.
pub fn fallback_loader(arch: &str) -> &'static str {
    match arch {
        "arm64" => "bootaa64.efi",
        "x86" => "bootia32.efi",
        "arm" => "bootarm.efi",
        _ => "bootx64.efi",
    }
}

/// What bcdboot copies to the boot partition, done here from `Windows\Boot`.
/// Returns what it did, for the log.
pub fn populate_boot_files(
    os: &Path,
    esp: &Path,
    o: &WinOptions,
    arch: &str,
) -> Result<Vec<String>, String> {
    let boot = find_ci(os, "Windows/Boot")
        .filter(|p| p.is_dir())
        .ok_or("The image has no Windows\\Boot folder, so it cannot be made bootable.")?;
    let mut log = Vec::new();
    let sub = |name: &str| find_ci(&boot, name).filter(|p| p.is_dir());

    if o.target.wants_uefi() {
        let ms = esp.join("EFI").join("Microsoft").join("Boot");
        // "Windows UEFI CA 2023" loaders live in the *_EX folders
        let ex = o.modern_secure_boot;
        let efi = if ex { sub("EFI_EX") } else { None };
        let (efi_dir, strip) = match efi {
            Some(d) => (d, true),
            None => {
                if ex {
                    log.push("This image has no EFI_EX folder: using the standard boot loaders".to_string());
                }
                (
                    sub("EFI").ok_or("The image has no Windows\\Boot\\EFI folder (UEFI boot files).")?,
                    false,
                )
            }
        };
        copy_dir(&efi_dir, &ms, strip, &mut log)?;
        let fonts = if ex { sub("Fonts_EX").map(|d| (d, true)) } else { None }
            .or_else(|| sub("Fonts").map(|d| (d, false)));
        if let Some((d, st)) = fonts {
            copy_dir(&d, &ms.join("Fonts"), st, &mut log)?;
        }
        if let Some(d) = sub("Resources") {
            copy_dir(&d, &ms.join("Resources"), false, &mut log)?;
        }
        let mgr = find_ci(&ms, "bootmgfw.efi")
            .filter(|p| p.is_file())
            .ok_or("bootmgfw.efi is missing from the image's boot files.")?;
        let fb = esp.join("EFI").join("Boot");
        std::fs::create_dir_all(&fb).map_err(|e| format!("cannot create {}: {}", fb.display(), e))?;
        std::fs::copy(&mgr, fb.join(fallback_loader(arch)))
            .map_err(|e| format!("cannot copy the fallback loader: {}", e))?;
        log.push(format!(
            "UEFI boot files copied (EFI\\Boot\\{})",
            fallback_loader(arch)
        ));
    }

    if o.target.wants_bios() {
        let pcat = sub("PCAT").ok_or("The image has no Windows\\Boot\\PCAT folder (BIOS boot files).")?;
        let bdir = esp.join("Boot");
        std::fs::create_dir_all(&bdir).map_err(|e| format!("cannot create {}: {}", bdir.display(), e))?;
        let mut got_bootmgr = false;
        let rd = std::fs::read_dir(&pcat).map_err(|e| format!("cannot read {}: {}", pcat.display(), e))?;
        let mut entries: Vec<_> = rd.filter_map(Result::ok).collect();
        entries.sort_by_key(|e| e.file_name());
        for e in entries {
            let name = e.file_name().to_string_lossy().into_owned();
            let path = e.path();
            let lower = name.to_lowercase();
            if path.is_dir() {
                copy_dir(&path, &bdir.join(&name), false, &mut log)?;
            } else if lower == "bootmgr" {
                std::fs::copy(&path, esp.join("bootmgr"))
                    .map_err(|er| format!("cannot copy bootmgr: {}", er))?;
                got_bootmgr = true;
            } else if lower == "bootnxt" {
                std::fs::copy(&path, esp.join("BOOTNXT"))
                    .map_err(|er| format!("cannot copy BOOTNXT: {}", er))?;
            } else {
                std::fs::copy(&path, bdir.join(&name))
                    .map_err(|er| format!("cannot copy {}: {}", name, er))?;
            }
        }
        if !got_bootmgr {
            return Err("bootmgr is missing from Windows\\Boot\\PCAT.".into());
        }
        if let Some(d) = sub("Fonts") {
            copy_dir(&d, &bdir.join("Fonts"), false, &mut log)?;
        }
        if let Some(d) = sub("Resources") {
            copy_dir(&d, &bdir.join("Resources"), false, &mut log)?;
        }
        log.push("BIOS boot files copied (bootmgr, Boot\\)".to_string());
    }
    Ok(log)
}

/// Writes the BCD store(s) the chosen target needs. Returns their paths.
pub fn write_stores(
    esp: &Path,
    o: &WinOptions,
    esp_part: &Part,
    os_part: &Part,
    locale: &str,
    description: &str,
) -> Result<Vec<PathBuf>, String> {
    let mut written = Vec::new();
    let mut one = |fw: Firmware, path: PathBuf| -> Result<(), String> {
        let store = bcd::Store {
            firmware: fw,
            system: esp_part.clone(),
            os: os_part.clone(),
            locale: locale.to_string(),
            description: description.to_string(),
            loader_guid: bcd::new_guid(),
            resume_guid: bcd::new_guid(),
            // bcdedit /set {default} recoveryenabled no
            recovery_enabled: false,
        };
        let bytes = bcd::build(&store)?;
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {}", dir.display(), e))?;
        }
        std::fs::write(&path, bytes).map_err(|e| format!("cannot write {}: {}", path.display(), e))?;
        written.push(path);
        Ok(())
    };
    if o.target.wants_uefi() {
        one(
            Firmware::Uefi,
            esp.join("EFI").join("Microsoft").join("Boot").join("BCD"),
        )?;
    }
    if o.target.wants_bios() {
        one(Firmware::Bios, esp.join("Boot").join("BCD"))?;
    }
    Ok(written)
}

/// Direct NTFS apply keeps all Windows file metadata. Returns false when
/// this wimlib was built without NTFS-3G (the caller then applies to a mount).
fn apply_direct(
    wimlib: &Path,
    wim: &Path,
    index: u32,
    part: &str,
    cancel: &AtomicBool,
) -> Result<bool, String> {
    let mut c = Command::new(wimlib);
    c.arg("apply").arg(wim).arg(index.to_string()).arg(part);
    let r = run_stream(c, cancel, |l| {
        if let Some(p) = parse_percent(l) {
            progress("write", p as u64, 100);
        }
    });
    match r {
        Ok(()) => Ok(true),
        Err(e) if e.to_lowercase().contains("ntfs-3g") && e.to_lowercase().contains("support") => Ok(false),
        Err(e) => Err(e),
    }
}

/// The whole Windows To Go job. The image is already mounted/inspected.
pub(crate) fn run(
    job: &Job,
    info: &disks::Disk,
    o: &WinOptions,
    wd: &mut Workdir,
    _src_root: &Path,
    report: &Report,
    cancel: &AtomicBool,
) -> Result<(), String> {
    let dev = job.dev.as_str();
    let regional = job.regional.as_ref();

    let install = report
        .install
        .as_ref()
        .ok_or("This image has no install.wim / install.esd, so there is no Windows to put on the drive.")?;
    if install.kind == InstallKind::Swm {
        return Err("Split images (install.swm) are not supported for Windows To Go.".into());
    }
    if o.target.wants_uefi() && o.target.wants_bios() && o.scheme == Scheme::Gpt {
        return Err("A GPT drive can only boot in UEFI mode.".into());
    }
    let lay = layout(info.size)?;

    // programs, checked before anything is erased
    let parted = require(&PARTED)?;
    let mkfs_fat = require(&MKFS_FAT)?;
    let mkfs_ntfs = require(&MKFS_NTFS)?;
    let wimlib = require(&WIMLIB)?;
    let sfdisk = require(&SFDISK)?;
    let grub = if o.target.wants_bios() {
        Some(require(&GRUB)?)
    } else {
        None
    };

    // which edition
    let count = parse_image_count(&wim_info_text(&wimlib, &install.path, None)?).unwrap_or(1);
    if o.edition > count {
        return Err(format!(
            "The image has {} edition(s); index {} does not exist.",
            count, o.edition
        ));
    }
    let wim_info = parse_image_info(&wim_info_text(&wimlib, &install.path, Some(o.edition))?);
    let arch = wim_info
        .arch
        .clone()
        .or_else(|| report.arch.map(|a| a.to_string()))
        .unwrap_or_else(|| "amd64".to_string());
    let name = wim_info.name.clone().unwrap_or_else(|| "Windows".to_string());
    stage(&format!("Edition {}: {} ({})", o.edition, name, arch));
    check_cancel(cancel)?;

    // ---- partition
    unmount_all(dev)?;
    stage("Erasing old signatures");
    run_quiet(command(Path::new("wipefs"), &s(&["-a", dev])), cancel)?;
    {
        let mut f = OpenOptions::new()
            .write(true)
            .open(dev)
            .map_err(|e| format!("cannot open {} for writing: {}", dev, e))?;
        f.write_all(&vec![0u8; MIB as usize])
            .map_err(|e| format!("write error: {}", e))?;
        f.sync_all().map_err(|e| format!("sync failed: {}", e))?;
    }
    check_cancel(cancel)?;
    stage(&format!(
        "Creating the {} partition table (boot partition + Windows partition)",
        if o.scheme == Scheme::Gpt { "GPT" } else { "MBR" }
    ));
    for args in parted_commands(dev, o, &lay) {
        run_quiet(command(&parted, &args), cancel)?;
    }
    let _ = Command::new("partprobe").arg(dev).output();
    let _ = Command::new("udevadm").arg("settle").output();
    let part_esp = partition_path(dev, 1);
    let part_os = partition_path(dev, 2);
    wait_for_node(&part_esp, cancel)?;
    wait_for_node(&part_os, cancel)?;

    // identities for the BCD, before anything refers to them
    let json = {
        let out = Command::new(&sfdisk)
            .arg("--json")
            .arg(dev)
            .output()
            .map_err(|e| format!("cannot run sfdisk: {}", e))?;
        if !out.status.success() {
            return Err(format!(
                "sfdisk failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            ));
        }
        String::from_utf8_lossy(&out.stdout).into_owned()
    };
    let ids = parse_sfdisk(&json, &[1, 2])?;

    // ---- format
    stage("Formatting the boot partition (FAT32) and the Windows partition (NTFS)");
    // No label on the boot partition: a label there is known to confuse some firmware.
    run_quiet(command(&mkfs_fat, &s(&["-F", "32", &part_esp])), cancel)?;
    run_quiet(
        command(&mkfs_ntfs, &crate::winworker::mkfs_args(Fs::Ntfs, &o.label, &part_os)),
        cancel,
    )?;
    let _ = Command::new("udevadm").arg("settle").output();
    check_cancel(cancel)?;

    // ---- apply Windows
    stage("Writing Windows to the drive (this takes a while)");
    let direct = apply_direct(&wimlib, &install.path, o.edition, &part_os, cancel)?;
    if direct {
        mount_data(wd, Fs::Ntfs, &part_os)?;
    } else {
        stage("wimlib has no NTFS-3G support: applying through a mount (file permissions are not kept)");
        mount_data(wd, Fs::Ntfs, &part_os)?;
        let mut c = Command::new(&wimlib);
        c.arg("apply")
            .arg(&install.path)
            .arg(o.edition.to_string())
            .arg(wd.usb());
        run_stream(c, cancel, |l| {
            if let Some(p) = parse_percent(l) {
                progress("write", p as u64, 100);
            }
        })?;
    }
    progress("write", 100, 100);
    check_cancel(cancel)?;
    let os_root = wd.usb();

    // ---- boot partition
    stage("Making the drive bootable (boot files and BCD)");
    let esp_root = wd.esp();
    wd.mount(&["-t", "vfat", &part_esp], &esp_root)
        .map_err(|e| format!("cannot mount the boot partition: {}", e))?;
    for l in populate_boot_files(&os_root, &esp_root, o, &arch)? {
        stage(&l);
    }
    let locale = regional
        .map(|r| r.locale.clone())
        .or_else(|| wim_info.language.clone())
        .unwrap_or_else(|| "en-US".to_string());
    write_stores(&esp_root, o, &ids[0], &ids[1], &locale, &name)?;
    check_cancel(cancel)?;

    // ---- user experience options + offline disks
    let params = unattend::Params {
        opts: o,
        regional,
        arch: &arch,
        ui_language: &locale,
    };
    if let Some(u) = unattend::build(&params) {
        let panther = os_root.join("Windows").join("Panther");
        std::fs::create_dir_all(&panther).map_err(|e| format!("cannot create {}: {}", panther.display(), e))?;
        std::fs::write(panther.join("unattend.xml"), u.xml)
            .map_err(|e| format!("cannot write unattend.xml: {}", e))?;
        for l in unattend::summary(o, regional) {
            stage(&format!("  {}", l));
        }
    }

    // ---- legacy BIOS
    if let Some(grub) = &grub {
        stage("Installing the BIOS boot loader (GRUB, hands over to bootmgr)");
        let bootdir = esp_root.join("boot");
        std::fs::create_dir_all(&bootdir)
            .map_err(|e| format!("cannot create {}: {}", bootdir.display(), e))?;
        let mut c = Command::new(grub);
        c.arg("--target=i386-pc")
            .arg(format!("--boot-directory={}", bootdir.display()))
            .arg("--modules=part_msdos fat ntldr search")
            .arg("--force")
            .arg(dev);
        run_stream(c, cancel, |_| {})?;
        let cfg_dir = bootdir.join("grub");
        std::fs::create_dir_all(&cfg_dir).map_err(|e| e.to_string())?;
        std::fs::write(cfg_dir.join("grub.cfg"), GRUB_CFG)
            .map_err(|e| format!("cannot write grub.cfg: {}", e))?;
    }

    stage("Flushing caches to the device");
    let _ = Command::new("sync").output();
    wd.unmount(&esp_root)?;
    wd.unmount(&os_root)?;
    let _ = Command::new("udevadm").arg("settle").output();
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::winopts::{all_off, Target};

    fn opts(scheme: Scheme, target: Target) -> WinOptions {
        let mut o = all_off();
        o.wtg = true;
        o.scheme = scheme;
        o.target = target;
        o.fs = Fs::Ntfs;
        o
    }

    #[test]
    fn layout_leaves_room() {
        assert!(layout(8 * 1024 * MIB).is_err());
        let l = layout(32 * 1024 * MIB).unwrap();
        assert_eq!(l.esp, (1, 301));
        assert_eq!(l.os, (301, 32 * 1024 - 1));
    }

    #[test]
    fn parted_for_gpt_and_mbr() {
        let l = layout(32 * 1024 * MIB).unwrap();
        let g = parted_commands("/dev/sdx", &opts(Scheme::Gpt, Target::Uefi), &l);
        assert!(g[0].contains(&"gpt".to_string()));
        assert!(!g.iter().any(|c| c.contains(&"boot".to_string())));
        let m = parted_commands("/dev/sdx", &opts(Scheme::Mbr, Target::Both), &l);
        assert!(m[0].contains(&"msdos".to_string()));
        assert!(m.iter().any(|c| c.contains(&"boot".to_string())));
        // UEFI-only MBR needs no active flag
        let mu = parted_commands("/dev/sdx", &opts(Scheme::Mbr, Target::Uefi), &l);
        assert!(!mu.iter().any(|c| c.contains(&"boot".to_string())));
    }

    #[test]
    fn sfdisk_gpt_and_dos() {
        let gpt = r#"{"partitiontable":{"label":"gpt","id":"533FC85C-E6B6-4BD4-B5CD-4BADC4B98D06","sectorsize":512,
          "partitions":[{"node":"/dev/x1","start":2048,"size":1,"uuid":"8CD00792-E072-44AA-BABE-EC71C6E27205"},
                        {"node":"/dev/x2","start":616448,"size":1,"uuid":"D218DB09-4505-4F72-B670-0683EE7D8036"}]}}"#;
        let p = parse_sfdisk(gpt, &[1, 2]).unwrap();
        assert_eq!(
            p[0],
            Part::gpt(
                "533fc85c-e6b6-4bd4-b5cd-4badc4b98d06",
                "8cd00792-e072-44aa-babe-ec71c6e27205"
            )
            .unwrap()
        );
        let dos = r#"{"partitiontable":{"label":"dos","id":"0x1a2b3c4d","sectorsize":4096,
          "partitions":[{"node":"/dev/x1","start":256,"size":1},{"node":"/dev/x2","start":76800,"size":1}]}}"#;
        let p = parse_sfdisk(dos, &[1, 2]).unwrap();
        assert_eq!(
            p[1],
            Part::Mbr {
                signature: 0x1a2b3c4d,
                offset: 76800 * 4096
            }
        );
        assert!(parse_sfdisk(dos, &[3]).is_err());
        assert!(parse_sfdisk("nope", &[1]).is_err());
    }

    fn fake_windows(root: &Path, ex: bool) {
        let b = root.join("Windows").join("Boot");
        for (d, f) in [
            ("EFI", "bootmgfw.efi"),
            ("EFI", "bootmgr.efi"),
            ("EFI", "memtest.efi"),
            ("EFI/en-US", "bootmgfw.efi.mui"),
            ("PCAT", "bootmgr"),
            ("PCAT", "bootnxt"),
            ("PCAT", "memtest.exe"),
            ("PCAT/en-US", "bootmgr.exe.mui"),
            ("Fonts", "segoen_slboot.ttf"),
            ("Resources", "bootres.dll"),
        ] {
            std::fs::create_dir_all(b.join(d)).unwrap();
            std::fs::write(b.join(d).join(f), format!("{}/{}", d, f)).unwrap();
        }
        if ex {
            std::fs::create_dir_all(b.join("EFI_EX")).unwrap();
            std::fs::write(b.join("EFI_EX").join("bootmgfw_EX.efi"), "ex-loader").unwrap();
            std::fs::create_dir_all(b.join("Fonts_EX")).unwrap();
            std::fs::write(b.join("Fonts_EX").join("segoen_slboot_EX.ttf"), "ex-font").unwrap();
        }
    }

    fn temp(name: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("ignite-wtg-{}-{}", name, std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        d
    }

    #[test]
    fn boot_files_for_uefi_and_bios() {
        let d = temp("both");
        let (os, esp) = (d.join("os"), d.join("esp"));
        fake_windows(&os, false);
        std::fs::create_dir_all(&esp).unwrap();
        let o = opts(Scheme::Mbr, Target::Both);
        populate_boot_files(&os, &esp, &o, "amd64").unwrap();
        for f in [
            "EFI/Microsoft/Boot/bootmgfw.efi",
            "EFI/Microsoft/Boot/en-US/bootmgfw.efi.mui",
            "EFI/Microsoft/Boot/Fonts/segoen_slboot.ttf",
            "EFI/Microsoft/Boot/Resources/bootres.dll",
            "EFI/Boot/bootx64.efi",
            "bootmgr",
            "BOOTNXT",
            "Boot/memtest.exe",
            "Boot/en-US/bootmgr.exe.mui",
            "Boot/Fonts/segoen_slboot.ttf",
        ] {
            assert!(esp.join(f).is_file(), "missing {}", f);
        }
        assert_eq!(
            std::fs::read(esp.join("EFI/Boot/bootx64.efi")).unwrap(),
            std::fs::read(esp.join("EFI/Microsoft/Boot/bootmgfw.efi")).unwrap()
        );
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn uefi_only_has_no_bios_files_and_arm64_name() {
        let d = temp("uefi");
        let (os, esp) = (d.join("os"), d.join("esp"));
        fake_windows(&os, false);
        std::fs::create_dir_all(&esp).unwrap();
        populate_boot_files(&os, &esp, &opts(Scheme::Gpt, Target::Uefi), "arm64").unwrap();
        assert!(esp.join("EFI/Boot/bootaa64.efi").is_file());
        assert!(!esp.join("bootmgr").exists());
        assert!(!esp.join("Boot").exists());
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn modern_secure_boot_uses_ex_files_without_suffix() {
        let d = temp("ex");
        let (os, esp) = (d.join("os"), d.join("esp"));
        fake_windows(&os, true);
        std::fs::create_dir_all(&esp).unwrap();
        let mut o = opts(Scheme::Gpt, Target::Uefi);
        o.modern_secure_boot = true;
        populate_boot_files(&os, &esp, &o, "amd64").unwrap();
        assert_eq!(
            std::fs::read_to_string(esp.join("EFI/Microsoft/Boot/bootmgfw.efi")).unwrap(),
            "ex-loader"
        );
        assert_eq!(
            std::fs::read_to_string(esp.join("EFI/Microsoft/Boot/Fonts/segoen_slboot.ttf")).unwrap(),
            "ex-font"
        );
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn missing_boot_folder_is_an_error() {
        let d = temp("none");
        std::fs::create_dir_all(d.join("os/Windows")).unwrap();
        std::fs::create_dir_all(d.join("esp")).unwrap();
        let e = populate_boot_files(&d.join("os"), &d.join("esp"), &opts(Scheme::Gpt, Target::Uefi), "amd64")
            .unwrap_err();
        assert!(e.contains("Windows\\Boot"));
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn stores_are_written_where_windows_looks() {
        let d = temp("bcd");
        let esp = d.join("esp");
        std::fs::create_dir_all(&esp).unwrap();
        let sys = Part::Mbr { signature: 7, offset: 1 << 20 };
        let os = Part::Mbr { signature: 7, offset: 301 << 20 };
        let w = write_stores(&esp, &opts(Scheme::Mbr, Target::Both), &sys, &os, "en-US", "Windows 11 Pro").unwrap();
        assert_eq!(w.len(), 2);
        for p in &w {
            let root = crate::hive::read(&std::fs::read(p).unwrap()).unwrap();
            assert!(root.find("Objects").is_some());
        }
        assert!(esp.join("EFI/Microsoft/Boot/BCD").is_file());
        assert!(esp.join("Boot/BCD").is_file());
        let _ = std::fs::remove_dir_all(&d);
    }

    /// End to end on a loop device, except for the FAT32 boot partition (the
    /// kernel of some build machines cannot mount vfat): the boot files go to
    /// a plain directory instead. Needs root, parted, ntfs-3g, wimlib.
    ///
    ///   IGNITE_TEST_DEV=/dev/loopN cargo test wtg_loop_device -- --ignored --nocapture
    #[test]
    #[ignore]
    fn wtg_loop_device() {
        let Ok(dev) = std::env::var("IGNITE_TEST_DEV") else { return };
        let scheme = if std::env::var("IGNITE_TEST_SCHEME").as_deref() == Ok("mbr") {
            Scheme::Mbr
        } else {
            Scheme::Gpt
        };
        let target = if scheme == Scheme::Gpt { Target::Uefi } else { Target::Both };
        let mut o = opts(scheme, target);
        o.label = "WTG".into();
        o.no_online_account = true;
        let cancel = AtomicBool::new(false);
        let size = std::fs::metadata(format!("/sys/class/block/{}/size", dev.trim_start_matches("/dev/")))
            .ok()
            .and_then(|_| std::fs::read_to_string(format!("/sys/class/block/{}/size", dev.trim_start_matches("/dev/"))).ok())
            .and_then(|t| t.trim().parse::<u64>().ok())
            .unwrap()
            * 512;
        // the real layout needs 12 GiB; shrink the ESP for the small test disk
        let lay = Layout { esp: (1, 41), os: (41, size / MIB - 1) };
        run_quiet(command(Path::new("wipefs"), &s(&["-a", &dev])), &cancel).unwrap();
        for a in parted_commands(&dev, &o, &lay) {
            run_quiet(command(Path::new("parted"), &a), &cancel).unwrap();
        }
        let _ = Command::new("partprobe").arg(&dev).output();
        std::thread::sleep(std::time::Duration::from_millis(800));
        let (p1, p2) = (partition_path(&dev, 1), partition_path(&dev, 2));
        run_quiet(command(Path::new("mkfs.ntfs"), &crate::winworker::mkfs_args(Fs::Ntfs, "WTG", &p2)), &cancel).unwrap();

        // a WIM with a miniature Windows tree
        let d = temp("loop");
        let tree = d.join("tree");
        fake_windows(&tree, false);
        std::fs::create_dir_all(tree.join("Windows/System32")).unwrap();
        std::fs::write(tree.join("Windows/System32/winload.efi"), "x").unwrap();
        let wim = d.join("install.wim");
        let st = Command::new("wimlib-imagex")
            .args(["capture"]).arg(&tree).arg(&wim).arg("Test Windows").arg("--no-acls")
            .output().unwrap();
        assert!(st.status.success(), "{}", String::from_utf8_lossy(&st.stderr));

        assert!(apply_direct(Path::new("wimlib-imagex"), &wim, 1, &p2, &cancel).unwrap());
        let mnt = d.join("os");
        std::fs::create_dir_all(&mnt).unwrap();
        let ok = Command::new("mount").args(["-t", "ntfs-3g", &p2]).arg(&mnt).status().unwrap();
        assert!(ok.success());
        let esp = d.join("esp");
        std::fs::create_dir_all(&esp).unwrap();
        let res = (|| -> Result<(), String> {
            populate_boot_files(&mnt, &esp, &o, "amd64")?;
            let json = String::from_utf8_lossy(&Command::new("sfdisk").arg("--json").arg(&dev).output().unwrap().stdout).into_owned();
            let ids = parse_sfdisk(&json, &[1, 2])?;
            // cross-check with the kernel's own view (blkid)
            let blk = |p: &str, k: &str| -> String {
                String::from_utf8_lossy(&Command::new("blkid").args(["-p", "-o", "value", "-s", k, p]).output().unwrap().stdout).trim().to_string()
            };
            match &ids[1] {
                Part::Gpt { part, .. } => {
                    let want = crate::bcd::guid_bytes(&blk(&p2, "PART_ENTRY_UUID")).ok_or("blkid GUID")?;
                    assert_eq!(*part, want, "partition GUID differs from blkid");
                }
                Part::Mbr { offset, .. } => {
                    let sectors: u64 = blk(&p2, "PART_ENTRY_OFFSET").parse().unwrap();
                    assert_eq!(*offset, sectors * 512, "partition offset differs from blkid");
                }
            }
            write_stores(&esp, &o, &ids[0], &ids[1], "en-US", "Test Windows")?;
            Ok(())
        })();
        let _ = Command::new("umount").arg(&mnt).status();
        res.unwrap();
        assert!(esp.join("EFI/Microsoft/Boot/BCD").is_file());
        // keep the stores for inspection with hivexregedit
        if let Ok(keep) = std::env::var("IGNITE_TEST_KEEP") {
            let _ = std::fs::create_dir_all(&keep);
            let _ = std::fs::copy(esp.join("EFI/Microsoft/Boot/BCD"), format!("{}/BCD-uefi", keep));
            if esp.join("Boot/BCD").is_file() {
                let _ = std::fs::copy(esp.join("Boot/BCD"), format!("{}/BCD-bios", keep));
            }
        }
        let _ = std::fs::remove_dir_all(&d);
    }
}
